[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Global Aid Alliance — Together We Respond</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet">
<style>
/* ===== RESET & BASE ===== */
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
html{scroll-behavior:smooth;-webkit-text-size-adjust:100%}
body{font-family:'Inter',system-ui,-apple-system,sans-serif;color:#2d2d2d;background:#fff;line-height:1.7;overflow-x:hidden}
a{color:inherit;text-decoration:none}
ul{list-style:none}
img{max-width:100%;display:block}
button{font-family:inherit;cursor:pointer;border:none;background:none}

/* ===== VARIABLES ===== */
:root{
  --red:#C41E3A;
  --red-dark:#a01830;
  --red-light:#f8e8eb;
  --navy:#1B3A5C;
  --navy-light:#254d78;
  --white:#FFFFFF;
  --gray-50:#f9fafb;
  --gray-100:#f3f4f6;
  --gray-200:#e5e7eb;
  --gray-300:#d1d5db;
  --gray-400:#9ca3af;
  --gray-500:#6b7280;
  --gray-600:#4b5563;
  --gray-700:#374151;
  --gray-800:#1f2937;
  --shadow-sm:0 1px 2px rgba(0,0,0,0.05);
  --shadow:0 4px 12px rgba(0,0,0,0.08);
  --shadow-lg:0 12px 40px rgba(0,0,0,0.12);
  --radius:8px;
  --max-w:1200px;
  --header-h:72px;
}

/* ===== UTILITY ===== */
.container{max-width:var(--max-w);margin:0 auto;padding:0 24px}
.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);border:0}
.btn{display:inline-flex;align-items:center;justify-content:center;padding:14px 32px;border-radius:var(--radius);font-weight:600;font-size:1rem;transition:all .25s ease;text-align:center;line-height:1.2}
.btn-primary{background:var(--red);color:#fff}
.btn-primary:hover{background:var(--red-dark);transform:translateY(-1px);box-shadow:0 4px 16px rgba(196,30,58,.35)}
.btn-secondary{background:transparent;color:#fff;border:2px solid #fff}
.btn-secondary:hover{background:rgba(255,255,255,.15);transform:translateY(-1px)}
.btn-navy{background:var(--navy);color:#fff}
.btn-navy:hover{background:var(--navy-light);transform:translateY(-1px);box-shadow:0 4px 16px rgba(27,58,92,.3)}
.btn-outline{background:transparent;color:var(--red);border:2px solid var(--red)}
.btn-outline:hover{background:var(--red);color:#fff}
.section-label{display:inline-block;font-size:.8rem;font-weight:700;letter-spacing:.12em;text-transform:uppercase;color:var(--red);margin-bottom:12px}
.section-title{font-size:2.25rem;font-weight:800;color:var(--navy);line-height:1.2;margin-bottom:16px}
.section-subtitle{font-size:1.1rem;color:var(--gray-500);max-width:640px;line-height:1.7}

/* ===== HEADER ===== */
.header{position:fixed;top:0;left:0;right:0;z-index:1000;background:rgba(255,255,255,.97);backdrop-filter:blur(8px);border-bottom:1px solid var(--gray-200);height:var(--header-h);transition:box-shadow .3s}
.header.scrolled{box-shadow:var(--shadow)}
.header-inner{display:flex;align-items:center;justify-content:space-between;height:100%;max-width:var(--max-w);margin:0 auto;padding:0 24px}
.logo{display:flex;align-items:center;gap:10px;font-weight:800;font-size:1.15rem;color:var(--navy)}
.logo-icon{width:36px;height:36px;background:var(--red);border-radius:50%;display:flex;align-items:center;justify-content:center;color:#fff;font-size:1.1rem;font-weight:800}
.nav-desktop{display:flex;align-items:center;gap:4px}
.nav-desktop a{padding:8px 14px;font-size:.9rem;font-weight:500;color:var(--gray-700);border-radius:6px;transition:all .2s}
.nav-desktop a:hover{color:var(--navy);background:var(--gray-100)}
.nav-desktop .btn-donate{background:var(--red);color:#fff;padding:10px 24px;font-weight:600;font-size:.9rem;border-radius:6px;margin-left:8px}
.nav-desktop .btn-donate:hover{background:var(--red-dark)}
.utility-links{display:flex;align-items:center;gap:16px;font-size:.8rem;color:var(--gray-500);margin-right:16px}
.utility-links a:hover{color:var(--navy)}
.hamburger{display:none;flex-direction:column;gap:5px;padding:8px;cursor:pointer}
.hamburger span{display:block;width:24px;height:2px;background:var(--navy);border-radius:2px;transition:all .3s}
.hamburger.active span:nth-child(1){transform:rotate(45deg) translate(5px,5px)}
.hamburger.active span:nth-child(2){opacity:0}
.hamburger.active span:nth-child(3){transform:rotate(-45deg) translate(5px,-5px)}

/* Mobile nav */
.mobile-nav{position:fixed;top:var(--header-h);left:0;right:0;background:#fff;border-bottom:1px solid var(--gray-200);padding:16px 24px;transform:translateY(-110%);transition:transform .35s ease;z-index:999;box-shadow:var(--shadow-lg)}
.mobile-nav.open{transform:translateY(0)}
.mobile-nav a{display:block;padding:14px 0;font-size:1rem;font-weight:500;color:var(--gray-700);border-bottom:1px solid var(--gray-100)}
.mobile-nav a:last-child{border-bottom:none}
.mobile-nav .btn-donate-mobile{display:block;text-align:center;background:var(--red);color:#fff;padding:14px;border-radius:var(--radius);font-weight:600;margin-top:12px}
.mobile-nav .utility-mobile{display:flex;gap:16px;font-size:.85rem;color:var(--gray-500);margin-top:12px;padding-top:12px;border-top:1px solid var(--gray-200)}

/* ===== HERO ===== */
.hero{position:relative;min-height:100vh;display:flex;align-items:center;background:linear-gradient(135deg,var(--navy) 0%,#0f2640 60%,#1a1a2e 100%);padding-top:calc(var(--header-h) + 40px);padding-bottom:80px;overflow:hidden}
.hero::before{content:'';position:absolute;inset:0;background:url("data:image/svg+xml,%3Csvg width='60' height='60' viewBox='0 0 60 60' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='none' fill-rule='evenodd'%3E%3Cg fill='%23ffffff' fill-opacity='0.03'%3E%3Cpath d='M36 34v-4h-2v4h-4v2h4v4h2v-4h4v-2h-4zm0-30V0h-2v4h-4v2h4v4h2V6h4V4h-4zM6 34v-4H4v4H0v2h4v4h2v-4h4v-2H6zM6 4V0H4v4H0v2h4v4h2V6h4V4H6z'/%3E%3C/g%3E%3C/g%3E%3C/svg%3E") repeat}
.hero-content{position:relative;z-index:1;max-width:720px}
.hero-label{display:inline-block;font-size:.8rem;font-weight:700;letter-spacing:.15em;text-transform:uppercase;color:rgba(255,255,255,.7);margin-bottom:20px}
.hero h1{font-size:3.5rem;font-weight:800;color:#fff;line-height:1.1;margin-bottom:20px;letter-spacing:-.02em}
.hero p{font-size:1.2rem;color:rgba(255,255,255,.8);line-height:1.7;margin-bottom:36px;max-width:560px}
.hero-buttons{display:flex;gap:16px;flex-wrap:wrap}
.hero-decoration{position:absolute;right:-80px;bottom:-40px;width:500px;height:500px;border-radius:50%;background:rgba(196,30,58,.15);filter:blur(80px);pointer-events:none}
.hero-decoration-2{position:absolute;right:100px;top:15%;width:300px;height:300px;border-radius:50%;background:rgba(255,255,255,.04);filter:blur(60px);pointer-events:none}

/* ===== MISSION ===== */
.mission{padding:100px 0;background:var(--gray-50)}
.mission-grid{display:grid;grid-template-columns:1fr 1fr;gap:64px;align-items:center}
.mission-text{font-size:1.05rem;color:var(--gray-600);line-height:1.8}
.mission-text p:first-child{font-size:1.15rem;color:var(--gray-700);margin-bottom:20px}
.mission-quote{border-left:4px solid var(--red);padding:20px 0 20px 24px;margin-top:28px;font-size:1.1rem;font-weight:600;color:var(--navy);font-style:italic;line-height:1.7}
.mission-image{position:relative;border-radius:12px;overflow:hidden;aspect-ratio:4/3;background:linear-gradient(135deg,#dfe9f3 0%,#c1d3e8 100%)}
.mission-image img{width:100%;height:100%;object-fit:cover}
.mission-image-placeholder{display:flex;flex-direction:column;align-items:center;justify-content:center;height:100%;color:var(--navy);opacity:.4;font-size:.9rem}
.mission-image-placeholder svg{width:64px;height:64px;margin-bottom:12px}

/* ===== IMPACT STATS ===== */
.impact{padding:80px 0;background:var(--navy);color:#fff}
.impact-header{text-align:center;margin-bottom:56px}
.impact-header .section-label{color:rgba(255,255,255,.6)}
.impact-header .section-title{color:#fff}
.impact-header .section-subtitle{color:rgba(255,255,255,.6);margin:0 auto}
.stats-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:32px;text-align:center}
.stat-card{padding:32px 16px;border-radius:12px;background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.08);transition:all .3s}
.stat-card:hover{background:rgba(255,255,255,.1);transform:translateY(-4px)}
.stat-number{font-size:3rem;font-weight:800;line-height:1;margin-bottom:8px;color:#fff}
.stat-number .accent{color:var(--red)}
.stat-label{font-size:.95rem;color:rgba(255,255,255,.7);line-height:1.4}
.stat-sub{font-size:.8rem;color:rgba(255,255,255,.4);margin-top:8px}

/* ===== PROGRAMS ===== */
.programs{padding:100px 0}
.programs-header{text-align:center;margin-bottom:56px}
.programs-header .section-subtitle{margin:0 auto}
.accordion{max-width:800px;margin:0 auto}
.accordion-item{border:1px solid var(--gray-200);border-radius:var(--radius);margin-bottom:12px;overflow:hidden;transition:all .3s}
.accordion-item:hover{border-color:var(--gray-300)}
.accordion-item.active{border-color:var(--red);box-shadow:0 2px 12px rgba(196,30,58,.1)}
.accordion-trigger{width:100%;display:flex;align-items:center;justify-content:space-between;padding:20px 24px;font-size:1.05rem;font-weight:600;color:var(--navy);text-align:left;transition:all .2s}
.accordion-trigger:hover{background:var(--gray-50)}
.accordion-trigger .icon{width:24px;height:24px;transition:transform .3s;flex-shrink:0;margin-left:16px;color:var(--gray-400)}
.accordion-item.active .accordion-trigger{color:var(--red)}
.accordion-item.active .accordion-trigger .icon{transform:rotate(180deg);color:var(--red)}
.accordion-body{max-height:0;overflow:hidden;transition:max-height .4s ease}
.accordion-body-inner{padding:0 24px 20px;color:var(--gray-600);line-height:1.7;font-size:.95rem}
.accordion-body-inner a{color:var(--red);font-weight:600;display:inline-block;margin-top:12px}
.accordion-body-inner a:hover{text-decoration:underline}

/* ===== GET INVOLVED ===== */
.involved{padding:100px 0;background:var(--gray-50)}
.involved-header{text-align:center;margin-bottom:56px}
.involved-header .section-subtitle{margin:0 auto}
.involved-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:32px}
.involved-card{background:#fff;border-radius:12px;padding:40px 32px;border:1px solid var(--gray-200);transition:all .3s;text-align:center}
.involved-card:hover{transform:translateY(-4px);box-shadow:var(--shadow-lg);border-color:transparent}
.involved-icon{width:64px;height:64px;border-radius:16px;display:flex;align-items:center;justify-content:center;margin:0 auto 24px;font-size:1.5rem}
.involved-card:nth-child(1) .involved-icon{background:var(--red-light);color:var(--red)}
.involved-card:nth-child(2) .involved-icon{background:#e8f0fe;color:var(--navy)}
.involved-card:nth-child(3) .involved-icon{background:#fce8e6;color:#c41e3a}
.involved-card h3{font-size:1.25rem;font-weight:700;color:var(--navy);margin-bottom:12px}
.involved-card p{font-size:.95rem;color:var(--gray-500);line-height:1.7;margin-bottom:24px}
.involved-card .btn{width:100%}

/* ===== NEWS ===== */
.news{padding:100px 0}
.news-header{display:flex;align-items:flex-end;justify-content:space-between;margin-bottom:40px;flex-wrap:wrap;gap:16px}
.carousel-controls{display:flex;gap:8px}
.carousel-btn{width:44px;height:44px;border-radius:50%;border:1px solid var(--gray-300);display:flex;align-items:center;justify-content:center;color:var(--gray-500);transition:all .2s}
.carousel-btn:hover{background:var(--navy);color:#fff;border-color:var(--navy)}
.carousel-btn svg{width:18px;height:18px}
.news-track{overflow:hidden;border-radius:12px}
.news-slider{display:flex;transition:transform .5s ease}
.news-card{min-width:100%;padding:40px;background:var(--gray-50);border-radius:12px;display:flex;gap:32px;align-items:flex-start}
.news-card-content{flex:1}
.news-card-tag{display:inline-block;font-size:.75rem;font-weight:700;text-transform:uppercase;letter-spacing:.1em;color:var(--red);background:var(--red-light);padding:4px 12px;border-radius:20px;margin-bottom:16px}
.news-card h3{font-size:1.35rem;font-weight:700;color:var(--navy);margin-bottom:12px;line-height:1.3}
.news-card p{color:var(--gray-500);line-height:1.7;font-size:.95rem}
.news-card-image{width:280px;flex-shrink:0;border-radius:8px;overflow:hidden;aspect-ratio:3/2;background:linear-gradient(135deg,#e0e7ef 0%,#c5d3e3 100%);display:flex;align-items:center;justify-content:center;color:var(--navy);opacity:.3}
.news-dots{display:flex;justify-content:center;gap:8px;margin-top:24px}
.news-dot{width:10px;height:10px;border-radius:50%;background:var(--gray-300);cursor:pointer;transition:all .2s}
.news-dot.active{background:var(--red);width:28px;border-radius:5px}

/* ===== DONATE CTA ===== */
.donate-cta{padding:100px 0;background:linear-gradient(135deg,var(--navy) 0%,#0f2640 100%);color:#fff;position:relative;overflow:hidden}
.donate-cta::before{content:'';position:absolute;inset:0;background:url("data:image/svg+xml,%3Csvg width='60' height='60' viewBox='0 0 60 60' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='none' fill-rule='evenodd'%3E%3Cg fill='%23ffffff' fill-opacity='0.03'%3E%3Cpath d='M36 34v-4h-2v4h-4v2h4v4h2v-4h4v-2h-4zm0-30V0h-2v4h-4v2h4v4h2V6h4V4h-4zM6 34v-4H4v4H0v2h4v4h2v-4h4v-2H6zM6 4V0H4v4H0v2h4v4h2V6h4V4H6z'/%3E%3C/g%3E%3C/g%3E%3C/svg%3E") repeat}
.donate-cta .container{position:relative;z-index:1}
.donate-grid{display:grid;grid-template-columns:1fr 1fr;gap:64px;align-items:center}
.donate-info h2{font-size:2.5rem;font-weight:800;margin-bottom:16px;line-height:1.2}
.donate-info p{font-size:1.1rem;color:rgba(255,255,255,.7);line-height:1.7;margin-bottom:32px}
.impact-table{width:100%;border-collapse:separate;border-spacing:0 8px}
.impact-table td{padding:12px 16px;font-size:.95rem}
.impact-table td:first-child{font-weight:700;font-size:1.1rem;color:var(--red);white-space:nowrap;width:100px}
.impact-table td:last-child{color:rgba(255,255,255,.7);border-left:2px solid rgba(255,255,255,.1)}
.donate-action{text-align:center;padding:40px;background:rgba(255,255,255,.06);border-radius:16px;border:1px solid rgba(255,255,255,.1);backdrop-filter:blur(8px)}
.donate-action h3{font-size:1.5rem;font-weight:700;margin-bottom:12px}
.donate-action p{color:rgba(255,255,255,.6);margin-bottom:28px;font-size:.95rem;line-height:1.6}
.donate-action .btn{font-size:1.1rem;padding:16px 48px}
.donate-guarantee{font-size:.85rem;color:rgba(255,255,255,.4);margin-top:20px;line-height:1.5}

/* ===== FOOTER ===== */
.footer{padding:64px 0 32px;background:#0f1724;color:rgba(255,255,255,.6)}
.footer-grid{display:grid;grid-template-columns:1.5fr 1fr 1fr 1fr 1fr;gap:40px;margin-bottom:48px}
.footer-brand{font-size:1.1rem;font-weight:700;color:#fff;margin-bottom:12px;display:flex;align-items:center;gap:8px}
.footer-brand .logo-icon{width:28px;height:28px;font-size:.8rem}
.footer-desc{font-size:.85rem;line-height:1.7;margin-bottom:20px}
.social-links{display:flex;gap:12px}
.social-link{width:36px;height:36px;border-radius:50%;background:rgba(255,255,255,.08);display:flex;align-items:center;justify-content:center;transition:all .2s;font-size:.75rem;color:rgba(255,255,255,.5)}
.social-link:hover{background:var(--red);color:#fff}
.footer-col h4{font-size:.8rem;font-weight:700;text-transform:uppercase;letter-spacing:.1em;color:rgba(255,255,255,.4);margin-bottom:16px}
.footer-col a{display:block;font-size:.9rem;padding:4px 0;transition:color .2s}
.footer-col a:hover{color:#fff}
.footer-bottom{border-top:1px solid rgba(255,255,255,.08);padding-top:24px;display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:12px;font-size:.8rem;color:rgba(255,255,255,.3)}

/* ===== DONATE MODAL ===== */
.modal-overlay{position:fixed;inset:0;background:rgba(0,0,0,.6);z-index:2000;display:flex;align-items:center;justify-content:center;padding:24px;opacity:0;pointer-events:none;transition:opacity .3s}
.modal-overlay.active{opacity:1;pointer-events:all}
.modal{background:#fff;border-radius:16px;width:100%;max-width:520px;max-height:90vh;overflow-y:auto;transform:translateY(20px) scale(.97);transition:transform .3s;box-shadow:0 24px 80px rgba(0,0,0,.2)}
.modal-overlay.active .modal{transform:translateY(0) scale(1)}
.modal-header{display:flex;align-items:center;justify-content:space-between;padding:24px 28px;border-bottom:1px solid var(--gray-200)}
.modal-header h2{font-size:1.3rem;font-weight:700;color:var(--navy)}
.modal-close{width:36px;height:36px;border-radius:50%;display:flex;align-items:center;justify-content:center;color:var(--gray-400);transition:all .2s;font-size:1.2rem}
.modal-close:hover{background:var(--gray-100);color:var(--gray-700)}
.modal-body{padding:28px}
.amount-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-bottom:20px}
.amount-btn{padding:16px;border:2px solid var(--gray-200);border-radius:var(--radius);font-size:1.1rem;font-weight:700;color:var(--navy);text-align:center;transition:all .2s;cursor:pointer}
.amount-btn:hover{border-color:var(--red);color:var(--red)}
.amount-btn.selected{background:var(--red);color:#fff;border-color:var(--red)}
.amount-btn small{display:block;font-size:.7rem;font-weight:500;color:var(--gray-400);margin-top:4px}
.amount-btn.selected small{color:rgba(255,255,255,.7)}
.custom-amount{margin-bottom:24px}
.custom-amount label{display:block;font-size:.85rem;font-weight:600;color:var(--gray-700);margin-bottom:8px}
.custom-amount input{width:100%;padding:14px 16px;border:2px solid var(--gray-200);border-radius:var(--radius);font-size:1.1rem;font-weight:600;color:var(--navy);transition:border-color .2s}
.custom-amount input:focus{outline:none;border-color:var(--red)}
.custom-amount .dollar-sign{position:absolute;left:16px;top:50%;transform:translateY(-50%);color:var(--gray-400);font-weight:600}
.frequency-toggle{display:flex;gap:0;margin-bottom:24px;border:2px solid var(--gray-200);border-radius:var(--radius);overflow:hidden}
.frequency-btn{flex:1;padding:12px;text-align:center;font-weight:600;font-size:.9rem;color:var(--gray-500);transition:all .2s;cursor:pointer}
.frequency-btn.active{background:var(--navy);color:#fff}
.modal-impact{background:var(--gray-50);border-radius:var(--radius);padding:16px;margin-bottom:24px;font-size:.9rem;color:var(--gray-600);line-height:1.6}
.modal-impact strong{color:var(--red)}
.modal .btn-primary{width:100%;padding:16px;font-size:1.1rem}
.modal-note{text-align:center;font-size:.8rem;color:var(--gray-400);margin-top:12px;line-height:1.5}

/* ===== RESPONSIVE ===== */
@media(max-width:1024px){
  .hero h1{font-size:2.75rem}
  .mission-grid{grid-template-columns:1fr;gap:40px}
  .stats-grid{grid-template-columns:repeat(2,1fr)}
  .involved-grid{grid-template-columns:1fr}
  .donate-grid{grid-template-columns:1fr}
  .donate-action{margin-top:20px}
  .footer-grid{grid-template-columns:1fr 1fr 1fr}
  .footer-brand-col{grid-column:1/-1}
  .news-card{flex-direction:column-reverse}
  .news-card-image{width:100%;aspect-ratio:16/9}
}

@media(max-width:768px){
  .nav-desktop,.utility-links{display:none}
  .hamburger{display:flex}
  .hero h1{font-size:2.25rem}
  .hero p{font-size:1.05rem}
  .section-title{font-size:1.75rem}
  .stats-grid{grid-template-columns:1fr 1fr;gap:16px}
  .stat-number{font-size:2.25rem}
  .donate-info h2{font-size:2rem}
  .footer-grid{grid-template-columns:1fr 1fr}
  .amount-grid{grid-template-columns:repeat(2,1fr)}
}

@media(max-width:480px){
  .hero h1{font-size:1.9rem}
  .hero-buttons{flex-direction:column}
  .hero-buttons .btn{width:100%}
  .stats-grid{grid-template-columns:1fr 1fr}
  .stat-number{font-size:2rem}
