<script>
// ===== HEADER SCROLL =====
const header = document.getElementById('header');
window.addEventListener('scroll', () => {
  header.classList.toggle('scrolled', window.scrollY > 10);
});

// ===== MOBILE MENU =====
const hamburger = document.getElementById('hamburger');
const mobileNav = document.getElementById('mobileNav');

hamburger.addEventListener('click', () => {
  const isOpen = mobileNav.classList.toggle('open');
  hamburger.classList.toggle('active');
  hamburger.setAttribute('aria-expanded', isOpen);
  document.body.style.overflow = isOpen ? 'hidden' : '';
});

function closeMobileNav() {
  mobileNav.classList.remove('open');
  hamburger.classList.remove('active');
  hamburger.setAttribute('aria-expanded', 'false');
  document.body.style.overflow = '';
}

// ===== ANIMATED COUNTERS =====
function animateCounters() {
  const counters = document.querySelectorAll('.counter');
  counters.forEach(counter => {
    if (counter.dataset.animated) return;
    const target = +counter.dataset.target;
    const duration = 2000;
    const startTime = performance.now();

    function update(currentTime) {
      const elapsed = currentTime - startTime;
      const progress = Math.min(elapsed / duration, 1);
      const eased = 1 - Math.pow(1 - progress, 3);
      counter.textContent = Math.floor(eased * target);
      if (progress < 1) {
        requestAnimationFrame(update);
      } else {
        counter.textContent = target;
        counter.dataset.animated = 'true';
      }
    }
    requestAnimationFrame(update);
  });
}

const statsObserver = new IntersectionObserver((entries) => {
  entries.forEach(entry => {
    if (entry.isIntersecting) {
      animateCounters();
      statsObserver.unobserve(entry.target);
    }
  });
}, { threshold: 0.3 });

statsObserver.observe(document.getElementById('impact'));

// ===== ACCORDION =====
document.querySelectorAll('.accordion-trigger').forEach(trigger => {
  trigger.addEventListener('click', () => {
    const item = trigger.parentElement;
    const body = item.querySelector('.accordion-body');
    const inner = body.querySelector('.accordion-body-inner');
    const isOpen = item.classList.contains('active');

    // Close all
    document.querySelectorAll('.accordion-item.active').forEach(openItem => {
      openItem.classList.remove('active');
      openItem.querySelector('.accordion-trigger').setAttribute('aria-expanded', 'false');
      openItem.querySelector('.accordion-body').style.maxHeight = '0';
    });

    // Open clicked (if was closed)
    if (!isOpen) {
      item.classList.add('active');
      trigger.setAttribute('aria-expanded', 'true');
      body.style.maxHeight = inner.scrollHeight + 'px';
    }
  });
});

// ===== NEWS CAROUSEL =====
let currentSlide = 0;
const totalSlides = 4;
const slider = document.getElementById('newsSlider');
const dots = document.querySelectorAll('.news-dot');

function goToSlide(index) {
  currentSlide = ((index % totalSlides) + totalSlides) % totalSlides;
  slider.style.transform = `translateX(-${currentSlide * 100}%)`;
  dots.forEach((d, i) => d.classList.toggle('active', i === currentSlide));
}

document.getElementById('prevBtn').addEventListener('click', () => goToSlide(currentSlide - 1));
document.getElementById('nextBtn').addEventListener('click', () => goToSlide(currentSlide + 1));
dots.forEach(dot => dot.addEventListener('click', () => goToSlide(+dot.dataset.index)));

// Touch/swipe support
let touchStartX = 0;
const track = document.querySelector('.news-track');
track.addEventListener('touchstart', e => { touchStartX = e.changedTouches[0].screenX; }, { passive: true });
track.addEventListener('touchend', e => {
  const diff = touchStartX - e.changedTouches[0].screenX;
  if (Math.abs(diff) > 50) goToSlide(currentSlide + (diff > 0 ? 1 : -1));
}, { passive: true });

// ===== DONATE MODAL =====
let selectedAmount = 100;

function openModal() {
  document.getElementById('donateModal').classList.add('active');
  document.body.style.overflow = 'hidden';
}

function closeModal() {
  document.getElementById('donateModal').classList.remove('active');
  document.body.style.overflow = '';
}

function selectAmount(btn) {
  document.querySelectorAll('.amount-btn').forEach(b => b.classList.remove('selected'));
  btn.classList.add('selected');
  selectedAmount = +btn.dataset.amount;
  document.getElementById('customAmount').value = '';
  updateImpactMsg();
}

function clearPresetAmounts() {
  document.querySelectorAll('.amount-btn').forEach(b => b.classList.remove('selected'));
}

const impactMap = {
  25: 'Provides 5 emergency blankets for displaced families',
  50: 'Supplies a family with food and water for one week',
  100: 'Funds emergency shelter materials for a household',
  250: 'Equips a volunteer with disaster response training',
  500: 'Provides emergency supplies for multiple families',
  1000: 'Delivers major relief aid to an affected community'
};

function updateImpactMsg() {
  const custom = document.getElementById('customAmount').value;
  const amount = custom ? +custom : selectedAmount;
  const msg = impactMap[amount] || 'Every dollar counts toward saving lives';
  document.querySelector('.modal-impact').innerHTML =
    `Your <strong>$${amount.toLocaleString()}</strong> donation ${msg.toLowerCase().startsWith('every') ? '' : ''}${msg}. 91&cent; of every dollar goes directly to humanitarian services.`;
}

document.getElementById('customAmount').addEventListener('input', updateImpactMsg);

function selectFrequency(btn) {
  document.querySelectorAll('.frequency-btn').forEach(b => b.classList.remove('active'));
  btn.classList.add('active');
}

function submitDonation() {
  const custom = document.getElementById('customAmount').value;
  const amount = custom ? +custom : selectedAmount;
  const freq = document.querySelector('.frequency-btn.active').textContent;
  alert(`Thank you for your ${freq.toLowerCase()} donation of $${amount.toLocaleString()}! In a real implementation, you would be redirected to a secure payment processor.`);
  closeModal();
}

// Close modal on overlay click or Escape
document.getElementById('donateModal').addEventListener('click', e => {
  if (e.target === e.currentTarget) closeModal();
});
document.addEventListener('keydown', e => {
  if (e.key === 'Escape') closeModal();
});

// Smooth scroll offset for fixed header
document.querySelectorAll('a[href^="#"]').forEach(a => {
  a.addEventListener('click', e => {
    const target = document.querySelector(a.getAttribute('href'));
    if (target) {
      e.preventDefault();
      const y = target.getBoundingClientRect().top + window.scrollY - 80;
      window.scrollTo({ top: y, behavior: 'smooth' });
    }
  });
});
